options.customCss:
:root{
  --chat--header--background: linear-gradient(90deg,#2563eb,#1e40af);
  --chat--header--padding: 12px 16px;
  --chat--heading--font-size: 1rem;
  --chat--subtitle--font-size: 0.85rem;
  --chat--window--height: 620px;
}

/* --- Compact header / hero --- */
.chat-header,
.chat-window__header,
.header,
.n8n-chat-header,
.chat-hero,
.hero-banner {
  max-height: 78px !important;
  height: auto !important;
  padding: 10px 16px !important;
  overflow: hidden !important;
  background: linear-gradient(90deg,#2563eb,#1e40af) !important;
  box-shadow: none !important;
  border-bottom-left-radius: 12px !important;
  border-bottom-right-radius: 12px !important;
}

/* Title + subtitle smaller and aligned */
.chat-header .title,
.chat-window__header .title,
.chat-header__title,
.header-title,
.header .title {
  font-size: 1rem !important;
  font-weight: 600 !important;
  margin: 0 !important;
  line-height: 1.1 !important;
  color: #fff !important;
}

/* Subtitle */
.chat-header .subtitle,
.chat-window__header .subtitle,
.header-subtitle {
  font-size: 0.82rem !important;
  margin-top: 4px !important;
  color: rgba(255,255,255,0.92) !important;
}

/* Remove large empty space under header (safe padding reduction) */
.chat-window__body,
.chat-body,
.messages-list,
.chat-messages {
  padding-top: 10px !important;
}

/* Quick replies / options alignment (centered, compact) */
.quick-replies,
.options-list,
.buttons-list,
.chat-actions {
  display: block !important;
  max-width: 820px !important;
  margin: 8px auto !important;
  gap: 8px !important;
}

/* Message bubble width and spacing */
.chat-message {
  max-width: 72% !important;
  margin-bottom: 10px !important;
  box-shadow: 0 3px 10px rgba(2,6,23,0.06) !important;
}

/* Input bar slight lift */
.chat-input,
.chat-footer,
.footer {
  padding: 10px 14px !important;
  background: rgba(255,255,255,0.98) !important;
}

/* Optional: hide very large hero image if present */
.chat-hero .hero-image,
.hero-banner .hero-image {
  max-height: 0 !important;
  opacity: 0 !important;
  visibility: hidden !important;
}

/* Fallback safe visual polish */
.chat-window {
  border-radius: 14px !important;
  overflow: hidden !important;
}
